/* Fonts */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
:root{--primary:#2ED573;--primary-dark:#22C064;--primary-darker:#169A4D;--surface:#fff;--surface-alt:#f8f9fa;--text-primary:#1f2937;--text-muted:#6c757d;--border-color:#f1f3f5;--wa-gradient:linear-gradient(135deg,var(--primary) 0%,var(--primary-dark) 55%,var(--primary-darker) 100%);}body{font-family:Inter,sans-serif!important;background:var(--surface-alt)!important;color:var(--text-primary)!important;}h1,h2,h3,h4,h5,h6{font-weight:700!important;line-height:1.2!important;letter-spacing:-.01em}.navbar,.main-content .navbar-top{background:#fff!important;border-bottom:1px solid var(--border-color)!important}.navbar-nav{font-weight:600}.navbar-nav .nav-link{color:var(--text-primary)!important}.navbar-nav .nav-link.active{background:var(--wa-gradient)!important;color:#fff!important;border-radius:.75rem!important}.btn-primary{background:var(--wa-gradient)!important;color:#fff!important;border:0!important;border-radius:.75rem!important}.btn-outline-primary{color:var(--primary)!important;border-color:var(--primary)!important;border-radius:.75rem!important}.btn-outline-primary:hover{background:var(--primary)!important;color:#fff!important}.card{background:#fff!important;border:1px solid var(--border-color)!important;border-radius:1rem!important;box-shadow:0 .5rem 1.25rem rgba(17,24,39,.08)!important}.card-hover{transition:transform .2s ease,box-shadow .2s ease}.card-hover:hover{transform:translateY(-4px);box-shadow:0 1rem 2.5rem rgba(17,24,39,.14)!important}.form-control,.form-select{border:1px solid #e9ecef!important;border-radius:.75rem!important;padding:.625rem .875rem!important;box-shadow:none!important}.form-control:focus,.form-select:focus{border-color:var(--primary)!important;box-shadow:0 0 0 .2rem rgba(46,213,115,.18)!important}.nav-pills .nav-link{border:1px solid var(--primary);color:var(--primary)!important;border-radius:.75rem!important}.nav-pills .nav-link.active{background:var(--wa-gradient)!important;color:#fff!important;border:0!important}.gradient-wa{background:var(--wa-gradient)!important;color:#fff!important}.text-gradient{background:var(--wa-gradient);-webkit-background-clip:text;-webkit-text-fill-color:transparent}.nav-blur{background-color:rgba(255,255,255,.88)!important;backdrop-filter:saturate(180%) blur(8px);-webkit-backdrop-filter:saturate(180%) blur(8px);border-bottom:1px solid var(--border-color)!important}
